parameters.jsCode:
var item = $input.first().json;
var title = String(item.title || 'Latest Tech Development').trim();
var link = String(item.link || 'https://www.bbc.com/news/technology').trim();
var snippet = String(item.contentSnippet || item.content || '').replace(/<[^>]*>/g, '').trim().slice(0, 300);

var prompt = 'Write a comprehensive, professional, 750+ word educational article based on this news topic: "' + title + '".\n\n' +
'Summary: ' + snippet + '\n' +
'Source: ' + link + '\n\n' +
'Respond ONLY with valid JSON in this exact structure:\n' +
'{\n' +
'  "title": "Clear descriptive headline",\n' +
'  "excerpt": "2 sentence engaging summary",\n' +
'  "category": "technology-ai",\n' +
'  "content": "<p>Full HTML formatted article body with multiple paragraphs, h2 headings, and informative breakdown (750+ words)...</p>",\n' +
'  "sources": [{"title": "Original News Report", "url": "' + link + '"}]\n' +
'}';

return [{ json: { originalTitle: title, originalLink: link, prompt: prompt } }];

var rawText = '';
try {
  rawText = $input.first().json.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini API response did not contain candidates: ' + JSON.stringify($input.first().json));
}

var cleaned = rawText.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
var article = JSON.parse(cleaned);

var slug = (article.title || 'article')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 75);

var words = String(article.content || '').replace(/<[^>]*>/g, ' ').split(/\s+/).filter(Boolean).length;
var readingTime = Math.max(1, Math.round(words / 225));
var now = new Date().toISOString();

var cleanHeadline = String(article.title || '').replace(/['"]/g, '').trim();
var imgPrompt = encodeURIComponent('editorial photography of ' + cleanHeadline + ', photorealistic, modern journalistic style, cinematic lighting, 8k, high quality editorial publication');
var realAiImageUrl = 'https://image.pollinations.ai/prompt/' + imgPrompt + '?width=1200&height=675&nologo=true';

var articlePayload = {
  slug: slug,
  title: article.title,
  excerpt: article.excerpt || article.title,
  content: article.content,
  category: article.category || 'technology-ai',
  image: realAiImageUrl,
  imageAlt: article.title,
  heroImage: realAiImageUrl,
  heroImageAlt: article.title,
  heroImageCaption: 'AI generated visual editorial representation of ' + cleanHeadline,
  sources: article.sources || [],
  readingTime: readingTime,
  wordCount: words,
  publishedAt: now,
  approvedAt: now,
  approvedBy: 'Christian Agbodzi',
  reviewer: 'Christian Agbodzi',
  approved: true,
  status: 'published'
};

var jsonString = JSON.stringify(articlePayload, null, 2);
var b64Content = Buffer.from(jsonString).toString('base64');

return [{
  json: {
    slug: slug,
    title: article.title,
    readingTime: readingTime,
    wordCount: words,
    imageUrl: realAiImageUrl,
    base64Content: b64Content,
    url: 'https://signalnestnews.vercel.app/articles/' + slug
  }
}];

